import ast, pathlib
for p in pathlib.Path("meta_catalog").glob("*.py"):
    tree = ast.parse(p.read_text())
    imported = {}
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom):
            for a in node.names:
                imported[a.asname or a.name] = node.lineno
    src = p.read_text()
    unused = [n for n in imported if n != "*" and src.count(n) <= 1]
    if unused:
        print(p, "possibly unused:", unused)
EOF

